func walkFolder(ctx context.Context, filesystem fs.FS, rootPath string, currentFolder string, results walkResults) error {
	children, stats, err := loadDir(ctx, filesystem, currentFolder)
	if err != nil {
		return err
	}
	for _, c := range children {
		err := walkFolder(ctx, filesystem, rootPath, c, results)
		if err != nil {
